#!/usr/bin/env python3
from pathlib import Path
p=Path("public/index.html")
if not p.exists() or not Path("public/navigation-controller.js").exists():raise SystemExit("Run from repository root")
s=p.read_text()
if "/mobile-navigation-refinement.js" in s:raise SystemExit("Already installed")
if s.count("</head>")!=1 or s.count("</body>")!=1:raise SystemExit("Unexpected HTML structure")
s=s.replace("</head>",'<link rel="stylesheet" href="/mobile-navigation-refinement.css?v=1"></head>')
s=s.replace("</body>",'<script src="/mobile-navigation-refinement.js?v=1" defer></script></body>')
Path("public/mobile-navigation-refinement.js").write_text("(()=>{'use strict';\nconst pages={trips:'tripsPage',wishlist:'wishlistPage',shopping:'shoppingPage',towing:'towingPage',maintenance:'maintenancePage',checklists:'checklistsPage',service:'servicePage',payload:'payloadPage'};\nfunction init(){\n const header=document.querySelector('body>header'),menu=document.querySelector('.ux-menu-toggle');\n if(header&&menu&&menu.parentElement===header)header.insertBefore(menu,header.firstElementChild);\n const links={};\n Object.entries(pages).forEach(([key,id])=>{\n  const section=document.getElementById(id);if(!section)return;\n  const link=document.createElement('a');link.className='mnr-home-link';\n  link.href='#dashboard';link.dataset.uxGo='dashboard';\n  link.textContent='← Dashboard';link.setAttribute('aria-label','Back to dashboard');\n  section.insertBefore(link,section.firstChild);links[key]=link;\n });\n function sync(){\n  const page=document.body.dataset.currentPage||'dashboard';\n  const mobile=matchMedia('(max-width:900px)').matches;\n  Object.entries(links).forEach(([key,link])=>{\n   link.hidden=!mobile||(key!==page&&!(key==='checklists'&&page==='profile'));\n  });\n }\n window.addEventListener('planner:navigate',sync);\n window.addEventListener('resize',sync,{passive:true});\n sync();\n}\nif(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();\n})();")
Path("public/mobile-navigation-refinement.css").write_text('@media(max-width:900px){\nbody>header{justify-content:flex-start!important}\nbody>header>.ux-menu-toggle{order:0!important;flex:0 0 auto!important;margin:0!important;min-width:44px!important;min-height:44px!important}\nbody>header>div:first-of-type{order:1!important;flex:1 1 auto!important;min-width:0!important}\nbody>header>.header-controls{order:2!important}\n.mnr-home-link{display:inline-flex!important;align-items:center;gap:5px;color:#236775!important;font-size:13px!important;font-weight:650!important;text-decoration:none!important;border-radius:7px!important;padding:7px 4px!important;margin:0 0 5px!important;min-height:32px!important}\n.mnr-home-link:focus-visible{outline:3px solid #268d9a;outline-offset:2px}\n.mnr-home-link[hidden]{display:none!important}\n}\n@media(min-width:901px){.mnr-home-link{display:none!important}}')
p.write_text(s)
print("Added left-side menu and Dashboard return links. No SQL migration.")
